// ACT-EMU-003: deploy/scripts/fetch-emu-cores.sh against a fake local HTTP server on port 8095 (install.test.mjs style).
// Nothing is downloaded from the internet; the server hands out generated bytes. Run with: node --test "scripts/*.test.mjs"
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { createHash } from 'node:crypto';
import { existsSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { createServer } from 'node:http';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { after, before, test } from 'node:test';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const script = join(root, 'deploy', 'scripts', 'fetch-emu-cores.sh').replaceAll('\\', '/');
const shPath = (p) =>
  p.replaceAll('\\', '/').replace(/^([A-Za-z]):/, (_, d) => `/${d.toLowerCase()}`);
const BASE = 'https://cdn.emulatorjs.org/4.2.3/data/';
const PORT = 8095;
const sha = (b) => createHash('sha256').update(b).digest('hex');

const A = Buffer.from('7z-pretend core archive A');
const B = Buffer.from('pretend helper script B, a bit longer');
let responses = {}; // url path -> Buffer | number (status)
let hits = [];
let server;

before(async () => {
  server = createServer((req, res) => {
    hits.push(req.url);
    const r = responses[req.url];
    if (typeof r === 'number' || r === undefined) {
      res.writeHead(typeof r === 'number' ? r : 404).end();
      return;
    }
    res.writeHead(200, { 'content-length': r.length }).end(r);
  });
  await new Promise((ok) => server.listen(PORT, '127.0.0.1', ok));
});
after(() => server.close());

function sandbox(rows) {
  const dir = mkdtempSync(join(tmpdir(), 'sr-emu-'));
  const lock = join(dir, 'test.lock');
  writeFileSync(
    lock,
    '# test pins\n' +
      rows
        .map(([dest, body]) => `${dest}\t${BASE}${dest}\t${sha(body)}\t${body.length}\tGPL-2.0\n`)
        .join(''),
  );
  responses = {};
  hits = [];
  return { dir, lock, dest: join(dir, 'served') };
}

function runAsync(sb, extra = [], opts = {}) {
  const { base = `http://127.0.0.1:${PORT}`, lock = sb.lock } = opts;
  const args = [shPath(script), '--dest', shPath(sb.dest), '--lock', shPath(lock), ...extra];
  if (base) args.push('--base-url', base);
  return new Promise((ok) => {
    const p = spawn('sh', args, { env: process.env });
    let out = '';
    p.stdout.on('data', (d) => (out += d));
    p.stderr.on('data', (d) => (out += d));
    p.on('close', (code) => ok({ status: code, out }));
  });
}

test('happy path, then skip, then --force, then --verify-only', async () => {
  const sb = sandbox([
    ['cores/a.data', A],
    ['compression/b.js', B],
  ]);
  responses['/cores/a.data'] = A;
  responses['/compression/b.js'] = B;

  const first = await runAsync(sb);
  assert.equal(first.status, 0, first.out);
  assert.deepEqual(readFileSync(join(sb.dest, 'cores/a.data')), A);
  assert.deepEqual(readFileSync(join(sb.dest, 'compression/b.js')), B);
  assert.equal(hits.length, 2);
  assert.match(first.out, /fetched {2}cores\/a\.data/);

  const second = await runAsync(sb);
  assert.equal(second.status, 0, second.out);
  assert.equal(hits.length, 2, 'files that match are not requested again');
  assert.match(second.out, /ok {7}cores\/a\.data/);

  const forced = await runAsync(sb, ['--force']);
  assert.equal(forced.status, 0, forced.out);
  assert.equal(hits.length, 4);

  assert.equal((await runAsync(sb, ['--verify-only'], { base: '' })).status, 0);
  writeFileSync(join(sb.dest, 'cores/a.data'), 'tampered');
  const v = await runAsync(sb, ['--verify-only'], { base: '' });
  assert.equal(v.status, 1);
  assert.match(v.out, /MISSING {2}cores\/a\.data/);
  rmSync(sb.dir, { recursive: true, force: true });
});

test('a digest mismatch discards the file and exits 1', async () => {
  const sb = sandbox([['cores/a.data', A]]);
  const wrong = Buffer.from('7z-pretend core archive X'); // same length as A, other bytes
  assert.equal(wrong.length, A.length);
  responses['/cores/a.data'] = wrong;
  const r = await runAsync(sb);
  assert.equal(r.status, 1, r.out);
  assert.match(r.out, /digest mismatch for cores\/a\.data/);
  assert.equal(
    existsSync(join(sb.dest, 'cores/a.data')),
    false,
    'the wrong file must not be installed',
  );
  assert.deepEqual(readdirSync(join(sb.dest, 'cores')), [], 'no .part file is left behind');
  rmSync(sb.dir, { recursive: true, force: true });
});

test('a longer file, a 404 and a mismatching size fail without installing anything', async () => {
  const sb = sandbox([['cores/a.data', A]]);
  responses['/cores/a.data'] = Buffer.concat([A, Buffer.alloc(10_000, 120)]);
  let r = await runAsync(sb);
  assert.equal(r.status, 1, r.out);
  assert.equal(existsSync(join(sb.dest, 'cores/a.data')), false);

  responses = {}; // now everything is a 404
  r = await runAsync(sb);
  assert.equal(r.status, 1, r.out);
  assert.match(r.out, /download failed/);
  assert.equal(existsSync(join(sb.dest, 'cores/a.data')), false);
  rmSync(sb.dir, { recursive: true, force: true });
});

test('refuses a plain-http mirror that is not loopback, and an unsafe pin list', async () => {
  const sb = sandbox([['cores/a.data', A]]);
  let r = await runAsync(sb, [], { base: 'http://mirror.example' });
  assert.equal(r.status, 1);
  assert.match(r.out, /--base-url must be https/);

  const evil = join(sb.dir, 'evil.lock');
  writeFileSync(evil, `../escape.data\t${BASE}x\t${sha(A)}\t${A.length}\tGPL-2.0\n`);
  r = await runAsync(sb, [], { lock: evil });
  assert.equal(r.status, 1);
  assert.match(r.out, /unsafe destination/);

  writeFileSync(evil, `a.data\thttp://evil.example/x\t${sha(A)}\t${A.length}\tGPL-2.0\n`);
  r = await runAsync(sb, [], { lock: evil });
  assert.equal(r.status, 1);
  assert.match(r.out, /does not start with/);
  rmSync(sb.dir, { recursive: true, force: true });
});

test('the real pin list names only allowed cores and well-formed digests', () => {
  const rows = readFileSync(join(root, 'deploy', 'emu-cores.lock'), 'utf8')
    .split('\n')
    .filter((l) => l && !l.startsWith('#'))
    .map((l) => l.split('\t'));
  assert.ok(rows.length >= 7);
  for (const [dest, url, digest, bytes] of rows) {
    assert.ok(url.startsWith(BASE), url);
    assert.match(digest, /^[0-9a-f]{64}$/);
    assert.ok(
      Number(bytes) > 0 && Number(bytes) < 5_000_000,
      `${dest} is larger than a core archive`,
    );
    assert.doesNotMatch(dest, /snes9x|genesis_plus_gx|picodrive|fbneo|fbalpha|mame|nestopia/);
  }
});
